```ts
import type { AnimationGroup } from "@babylonjs/lite";
import { playAnimation, stopAnimation } from "@babylonjs/lite";

/**
 * Freezes a playing clip at its current moment so hand-set node transforms
 * stay as set. Returns `resume`, which plays the clip on from that moment.
 *
 * Why stop and not pause: the docs say a paused glTF group still evaluates
 * on every tick (to keep the pose current), which would overwrite our edits
 * each frame. A stopped group's tick returns immediately, so it writes nothing.
 * stopAnimation resets currentTime to 0, so we save the time and speed first
 * and restore them on resume.
 */
export function freezeForPosing(group: AnimationGroup): () => void {
    const frozenTime = group.currentTime;
    const speedRatio = group.speedRatio;
    let frozen = true;

    stopAnimation(group);

    return function resume(): void {
        if (!frozen) {
            return;
        }
        frozen = false;
        playAnimation(group);
        // Set after play in case play restarts from 0; speed is the clip's own.
        group.currentTime = frozenTime;
        group.speedRatio = speedRatio;
    };
}
```

I added `src/pose-mode.ts`. It saves the clip's time and speed, calls `stopAnimation` so the clip stops evaluating and writing to nodes, and `resume` calls `playAnimation` and then restores the saved time and speed.

I could not run anything, so several things are unverified:
- I used stop instead of pause because the doc says paused glTF groups still evaluate each tick, which would overwrite your edits.
- The docs don't say whether `stopAnimation` writes the rest pose to the nodes, or whether `playAnimation` restarts from 0. If stop does reset the rig, the frozen pose would visibly jump to rest; I assumed it doesn't.
- I reassign `currentTime` after `playAnimation` to cover a restart from 0.
- If you use the weighted mixers, a stopped group may behave differently from what I assumed.
